export function getLocalizedQuote(kanji: string, fallbackVi: string, lang: NativeLanguage): string {
  return DAILY_QUOTE_TRANSLATIONS[kanji]?.[lang] || DAILY_QUOTE_TRANSLATIONS[kanji]?.vi || fallbackVi;
}

