export function detectInitialLanguage(): NativeLanguage {
  if (typeof window !== "undefined") {
    try {
      const stored = (localStorage.getItem("nq_native_language") || localStorage.getItem("nihonquest_native_language")) as NativeLanguage | null;
      if (stored && SUPPORTED_LANGUAGES.some((l) => l.code === stored)) {
        return stored;
      }
      const match = document.cookie.match(/(?:^|;\s*)nq_native_language=([^;]+)/);
      if (match && match[1] && SUPPORTED_LANGUAGES.some((l) => l.code === match[1])) {
        return match[1] as NativeLanguage;
      }
      const navLang = (navigator.language || (navigator as any).userLanguage || "").toLowerCase();
      if (navLang.startsWith("zh-tw") || navLang.startsWith("zh-hk") || navLang.startsWith("zh-hant")) return "zh-TW";
      if (navLang.startsWith("zh")) return "zh-CN";
      if (navLang.startsWith("vi")) return "vi";
      if (navLang.startsWith("ko")) return "ko";
      if (navLang.startsWith("es")) return "es";
      if (navLang.startsWith("fr")) return "fr";
      if (navLang.startsWith("de")) return "de";
      if (navLang.startsWith("id")) return "id";
      if (navLang.startsWith("th")) return "th";
      if (navLang.startsWith("ru")) return "ru";
      if (navLang.startsWith("pt")) return "pt";
      if (navLang.startsWith("en")) return "en";
    } catch {
      // Ignore
    }
  }
  return "en";
}

export function LanguageProvider({
  children,
  initialLanguage = "en",
}: {
  children: React.ReactNode;
  initialLanguage?: NativeLanguage;
}) {
  const [nativeLanguage, setNativeLanguageState] = useState<NativeLanguage>(initialLanguage);

  useEffect(() => {
    try {
      const detected = detectInitialLanguage();
      setNativeLanguageState(detected);
    } catch {
      // Ignore
    }

    const handleLangChange = (e: Event) => {
      const customEvent = e as CustomEvent<{ lang?: NativeLanguage }>;
      const nextLang = customEvent.detail?.lang;
      if (nextLang && SUPPORTED_LANGUAGES.some((l) => l.code === nextLang)) {
        setNativeLanguageState(nextLang);
      }
    };

    const handleStorageChange = (e: StorageEvent) => {
      if ((e.key === "nq_native_language" || e.key === "nihonquest_native_language") && e.newValue) {
        if (SUPPORTED_LANGUAGES.some((l) => l.code === e.newValue)) {
          setNativeLanguageState(e.newValue as NativeLanguage);
        }
      }
    };

    window.addEventListener("nq:language-changed", handleLangChange);
    window.addEventListener("storage", handleStorageChange);
    return () => {
      window.removeEventListener("nq:language-changed", handleLangChange);
      window.removeEventListener("storage", handleStorageChange);
    };
  }, []);

  const setNativeLanguage = useCallback((lang: NativeLanguage) => {
    if (!SUPPORTED_LANGUAGES.some((l) => l.code === lang)) return;
    setNativeLanguageState(lang);
    try {
      localStorage.setItem("nq_native_language", lang);
      localStorage.setItem("nihonquest_native_language", lang);
      document.cookie = `nq_native_language=${lang}; path=/; max-age=31536000; SameSite=Lax`;
      if (typeof window !== "undefined") {
        window.dispatchEvent(new CustomEvent("nq:language-changed", { detail: { lang } }));
      }
    } catch {
      // Ignore
    }
  }, []);

  const langInfo =
    SUPPORTED_LANGUAGES.find((l) => l.code === nativeLanguage) || SUPPORTED_LANGUAGES[0];

  const t = useCallback(
    (key: string, params?: Record<string, string | number>): string => {
      let raw: string =
        GLOBAL_APP_I18N[nativeLanguage]?.[key] ||
        DASHBOARD_PAGES_I18N[nativeLanguage]?.[key] ||
        PAGE_I18N_DICTIONARY[nativeLanguage]?.[key] ||
        EXTENDED_DICTIONARY[nativeLanguage]?.[key] ||
        DICTIONARY[nativeLanguage]?.[key] ||
        GLOBAL_APP_I18N.en?.[key] ||
        (nativeLanguage !== "vi"
          ? DASHBOARD_PAGES_I18N.en?.[key] || PAGE_I18N_DICTIONARY.en?.[key] || EXTENDED_DICTIONARY.en?.[key] || DICTIONARY.en?.[key]
          : "") ||
        GLOBAL_APP_I18N.vi?.[key] ||
        (nativeLanguage === "vi"
          ? DASHBOARD_PAGES_I18N.vi?.[key] || PAGE_I18N_DICTIONARY.vi?.[key] || EXTENDED_DICTIONARY.vi?.[key] || DICTIONARY.vi?.[key]
          : "") ||
        DASHBOARD_PAGES_I18N.en?.[key] ||
        PAGE_I18N_DICTIONARY.en?.[key] || EXTENDED_DICTIONARY.en?.[key] ||
        DICTIONARY.en?.[key] ||
        key;

      if (params && typeof raw === "string") {
        for (const [k, v] of Object.entries(params)) {
          raw = raw.replace(new RegExp(`\\{${k}\\}`, "g"), String(v));
        }
      }
      return raw;
    },
    [nativeLanguage]
  );

  return (
    <LanguageContext.Provider value={{ nativeLanguage, setNativeLanguage, langInfo, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useNativeLanguage() {
  const ctx = useContext(LanguageContext);
  if (!ctx) {
    const fallbackLang = detectInitialLanguage();
    const langInfo = SUPPORTED_LANGUAGES.find((l) => l.code === fallbackLang) || SUPPORTED_LANGUAGES[0];
    return {
      nativeLanguage: fallbackLang,
      setNativeLanguage: () => {},
      langInfo,
      t: (key: string, params?: Record<string, string | number>) => {
        let raw: string =
          DASHBOARD_PAGES_I18N[fallbackLang]?.[key] ||
          PAGE_I18N_DICTIONARY[fallbackLang]?.[key] || EXTENDED_DICTIONARY[fallbackLang]?.[key] ||
          DICTIONARY[fallbackLang]?.[key] ||
          (fallbackLang !== "vi"
            ? DASHBOARD_PAGES_I18N.en?.[key] || PAGE_I18N_DICTIONARY.en?.[key] || EXTENDED_DICTIONARY.en?.[key] || DICTIONARY.en?.[key]
            : "") ||
          DASHBOARD_PAGES_I18N.vi?.[key] ||
          PAGE_I18N_DICTIONARY.vi?.[key] || EXTENDED_DICTIONARY.vi?.[key] ||
          DICTIONARY.vi?.[key] ||
          key;
        if (params && typeof raw === "string") {
          for (const [k, v] of Object.entries(params)) {
            raw = raw.replace(new RegExp(`\\{${k}\\}`, "g"), String(v));
          }
        }
        return raw;
      },
    };
  }
  return ctx;
}

export function mapBackendError(rawError: string | undefined | null, t: (k: string) => string): string {
  if (!rawError) return "";
  const lower = rawError.toLowerCase();
  if (lower.includes("đã được đăng ký") || lower.includes("already registered") || lower.includes("已被注册") || lower.includes("已被註冊")) {
    return t("errEmailAlreadyExists") || "Email is already registered.";
  }
  if (
    lower.includes("không đúng") ||
    lower.includes("hết hạn") ||
    lower.includes("không hợp lệ") ||
    lower.includes("invalid") ||
    lower.includes("expired") ||
    lower.includes("không chính xác")
  ) {
    if (lower.includes("email")) {
      return t("errInvalidEmail") || "Invalid email address.";
    }
    if (lower.includes("mật khẩu") || lower.includes("password")) {
      return t("errInvalidPassword") || "Invalid password.";
    }
    return t("errOtpInvalidOrExpired") || "The verification code is incorrect or has expired.";
  }
  if (lower.includes("vui lòng đợi") || lower.includes("wait") || lower.includes("quá nhiều") || lower.includes("too many")) {
    return t("errRateLimit") || "Too many requests. Please wait before trying again.";
  }
  return rawError;
}
